def parse_grid(s, name):
    lines = [line.strip() for line in s.split('\n') if line.strip()]
    # Each row has space-separated values
    grid = [[int(c) for c in line.split(' ')] for line in lines]
    print(f"\n{name}: shape {len(grid)}x{len(grid[0])}")
    return grid

demo_in = parse_grid(demo_input_str, "Demo Input")
demo_out = parse_grid(demo_output_str, "Demo Output")

# Find horizontal lines in each
def find_hlines(grid):
    hlines = []
    for i, row in enumerate(grid):
        if all(v != 0 for v in row):
            hlines.append((i, set(row)))
    return hlines

print("\n=== Analysis ===")
